INSERT OR IGNORE INTO exercises (`id`, `name`, `category`, `muscle_groups`, `equipment`, `form_cues`, `created_at`, `form_video_url`, `tips`, `coach_hint`, `video_start_sec`, `video_source`, `video_title`, `video_length`, `video_status`, `video_checked_at`, `alt_video_url`, `alt_video_source`, `alt_video_status`, `tiktok_url`, `merged_into`, `cue_line`, `coach_note`) VALUES ('ex-a-skips', 'A-Skips', 'mobility', 'calves,hip_flexors,glutes', 'bodyweight', 'Light skip. Drive one knee to hip height, opposite arm swings, land under the hips on the ball of the foot.', 1776995558, 'https://www.youtube.com/watch?v=GQg9L28bi1g', 'Bouncy and quick, not high. | 2 x 20 yards.', 'Run-walk warm-up, once High-Knee March feels easy.', 117, 'Matt Holton', 'A Skip Running Drill', '6:05', 'live', 1792469580, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO exercises (`id`, `name`, `category`, `muscle_groups`, `equipment`, `form_cues`, `created_at`, `form_video_url`, `tips`, `coach_hint`, `video_start_sec`, `video_source`, `video_title`, `video_length`, `video_status`, `video_checked_at`, `alt_video_url`, `alt_video_source`, `alt_video_status`, `tiktok_url`, `merged_into`, `cue_line`, `coach_note`) VALUES ('ex-spiderman-tspine', 'Spiderman + T-Spine Rotation', 'mobility', 'hips,adductors,thoracic_spine', 'bodyweight', 'Low lunge, hand inside the front foot, turn the top arm up and follow it with your eyes. 5 per side.', 1776995558, 'https://www.youtube.com/watch?v=nOqMAsvRJ90', 'Same move as the World''s Greatest Stretch; consider merging the two.', 'Not in a template since migration 0019. Duplicate of the World''s Greatest Stretch.', NULL, 'Gabe Caldwell', 'Spider-Man Lunge w/ Thoracic Rotation', '0:24', 'live', 1792469580, 'https://www.youtube.com/watch?v=-CiWQ2IvY34', 'Squat University', 'live', NULL, 'ex-worlds-greatest-stretch', NULL, NULL);
INSERT OR IGNORE INTO exercises (`id`, `name`, `category`, `muscle_groups`, `equipment`, `form_cues`, `created_at`, `form_video_url`, `tips`, `coach_hint`, `video_start_sec`, `video_source`, `video_title`, `video_length`, `video_status`, `video_checked_at`, `alt_video_url`, `alt_video_source`, `alt_video_status`, `tiktok_url`, `merged_into`, `cue_line`, `coach_note`) VALUES ('ex-walking-knee-hugs', 'Walking Knee Hugs', 'mobility', 'hip_flexors,glutes', 'bodyweight', 'Step, hug one knee to the chest for a beat while standing tall, then walk through. 6 per side.', 1776995558, 'https://www.youtube.com/watch?v=0TbiswLwSAc', 'Rise onto the ball of the standing foot.', 'Not in a template since the static warm-up (migration 0019). Kept for reference.', NULL, 'Champion Physical Therapy and Performance', 'Walking Knee Hugs', '0:11', 'live', 1792469580, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO exercises (`id`, `name`, `category`, `muscle_groups`, `equipment`, `form_cues`, `created_at`, `form_video_url`, `tips`, `coach_hint`, `video_start_sec`, `video_source`, `video_title`, `video_length`, `video_status`, `video_checked_at`, `alt_video_url`, `alt_video_source`, `alt_video_status`, `tiktok_url`, `merged_into`, `cue_line`, `coach_note`) VALUES ('ex-walking-quad-pulls', 'Walking Quad Pulls', 'mobility', 'quads,hip_flexors', 'bodyweight', 'Step, pull the heel to the glute, squeeze that glute for a beat, walk through. 6 per side.', 1776995558, 'https://www.youtube.com/watch?v=yGN2Z6XkWNQ', 'Knees together.', 'Not in a template since migration 0019. Kept for reference.', NULL, 'Twin Cities Orthopedics', 'Dynamic Warmup Exercises | How to perform a Quad Stretch', '1:05', 'live', 1792469580, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
